CustomField.formula:
IF( ISPICKVAL(TSGCFG__Consolidation_Method__c, 'Average') && TSGCFG__MPSTotalCPCLineItem__c > 0,

TSGCFG__MPSSumofCPCBW__c / TSGCFG__MPSTotalCPCLineItem__c ,

IF( ABS(TSGCFG__MPSTotalMonoVolume__c - TSGCFG__MPSTotalVolumeIncludesBW__c) <>0, TSGCFG__MFP_Total_BW_Monthly_Cost__c  / ABS(TSGCFG__MPSTotalMonoVolume__c - TSGCFG__MPSTotalVolumeIncludesBW__c),

IF(TSGCFG__MPSTotalCPCLineItem__c > 0, TSGCFG__MPSSumofCPCBW__c / TSGCFG__MPSTotalCPCLineItem__c, 0)
)
)


